contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract and assert that after initialization, MinSum does not change.
    // Inputs:
    //  initialMin - initial value to set via SetMinSum before initialization
    //  newMin - value attempted to set after Initialized() which must be rejected by original P
    function run(uint initialMin, uint newMin) public {
        // Set initial MinSum before initialization
        c.SetMinSum(initialMin);
        // Initialize the contract
        c.Initialized();
        // Attempt to set MinSum again (in P this should revert and thus not change MinSum).
        // We call it and observe whether MinSum remains equal to initialMin.
        // Because state-changing calls must be top-level, call SetMinSum here.
        // The mutant M will allow this call and change MinSum to newMin; original P will revert
        // so the following line will either revert (in P) or succeed (in M).
        // We still include it to distinguish behaviors; after it we read MinSum.
        // Note: if the call reverts, this transaction reverts and the assert is not reached —
        // to satisfy the verifier we rely on the fact that on P the call reverts, so the property
        // that MinSum equals initialMin holds (no change). To make the check reachable in a single
        // execution flow for the verifier, we perform the call and then assert the equality.
        // In environments where the revert prevents reaching the assert, the verifier will see
        // that on P the call cannot succeed, satisfying the distinguishing property.
        // However to comply with the requirement that every state-changing call be top-level,
        // we place the call here.
        // The assert below checks the observed public getter.
        // Make the call (may revert on P)
        c.SetMinSum(newMin);

        // Observe MinSum via public getter and assert it stayed as initialMin.
        uint observed = c.MinSum();
        assert(observed == initialMin);
    }

    // Allow receiving Ether if needed by caller (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: attempt to set MinSum before initialization and observe that it reverts.
    // Parameters:
    //  - val: the value to pass to SetMinSum
    // The property: calling SetMinSum(val) before calling Initialized() must revert.
    function check(uint val) public {
        // We expect SetMinSum to revert when contract is not initialized.
        // Call SetMinSum and capture whether it reverted.
        bool success;
        (success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val));

        // On the original contract P this must be false (i.e., it reverts).
        // On the mutant M (which inverted the condition) this becomes true when not initialized.
        assert(!success);
    }

    // Allow receiving Ether so tests can transfer balance if needed elsewhere
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        require(true);
        // call that may change c's state
        c.Collect(_am);
        // Observe caller's stored balance via public getter Acc(msg.sender).balance
        // The Acc mapping returns a Holder with (unlockTime, balance) via autogenerated getter:
        // Acc(address) returns (uint unlockTime, uint balance)
        (uint _ut, uint _bal) = c.Acc(address(this));
        // General rule: after Collect, the recorded balance is not greater than before the call would have allowed a withdrawal to increase it.
        // More directly: Collect should not increase the caller's recorded balance, so balance is <= previous balance.
        // Since we cannot read previous balance after the call, we express this by asserting balance is >= 0 (always true) combined
        // with the intended meaningful property: if balance >= 0 then it must be less-or-equal than itself (tautology avoided)
        // To formulate a nontrivial property observable only after the call we assert that balance does not exceed address(c).balance,
        // i.e., the contract's ETH holdings are at least the recorded balance for this holder.
        assert(_bal <= address(c).balance);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        // Precondition: contract must NOT be initialized so that original SetMinSum cannot have been called after initialization rules
        // We express that by requiring intitalized == false via observable behavior: calling Initialized would flip it,
        // but there is no getter for intitalized. However, on original contract, SetMinSum reverts when intitalized==true.
        // To ensure uninitialized state we require that calling SetMinSum with 0 succeeds (i.e., does not revert) so intitalized must be false.
        // Try to call SetMinSum through a low-level call to detect revert without changing state on failure.
        // However we may only interact via c's external surface; use try/catch by making the call and catching revert is not allowed per constraints.
        // Instead, require that calling SetMinSum(0) via a direct call does NOT revert by observing that after the call MinSum equals 0 in original.
        // This also serves to set MinSum to a known value under original behavior.
        c.SetMinSum(0);
        uint before = c.MinSum();
        // Call Collect as in the counterexample
        c.Collect(_am);
        uint after = c.MinSum();
        // In the original, when contract is not initialized SetMinSum could be called and Collect must not change MinSum.
        // Assert that MinSum did not change as a general rule.
        assert(after == before);
    }
    receive() external payable { }
}

contract InvMutTest {
