    function run(uint withdraw) public payable {
        // precondition: contract not initialized
        require(c.intitalized() == false);
        // record MinSum before
        uint before = c.MinSum();
        // call Collect as in the counterexample
        c.Collect(withdraw);
        // observe MinSum after
        uint after = c.MinSum();
        // general rule: if not initialized, Collect should not change MinSum
        assert(after == before);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will invoke Collect as the same address as this test contract.
    // Precondition: the contract must be not initialized (intitalized == false).
    // We cannot read intitalized directly, so require that calling Initialized would succeed (i.e., it hasn't been set yet) is not allowed.
    // Instead we require that calling SetMinSum would not revert under original behavior: in original SetMinSum it reverts if intitalized==true,
    // so requiring that SetMinSum can be called and then reverting it back is not possible. Instead we rely on observing that Initialized() must not have been called by others.
    // Simpler: require that address of this test currently has zero recorded balance so Collect won't change balances; but the core rule concerns MinSum unchanged when not initialized.

    // To observe MinSum, use the public getter c.MinSum(). We will record it, call Collect, then assert unchanged.
    function run(uint _am) public payable {
        // No special precondition available through public surface; require true.
        require(true);
        uint before = c.MinSum();
        // Call Collect from this contract; send no Ether (Collect is payable but not required)
        c.Collect(_am);
        uint after_ = c.MinSum();
        assert(after_ == before);
    }
    receive() external payable { }
}

