pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - addr: the actor who will put funds and then call Collect
    // - putAmt: amount to send to Put (and fallback)
    // - collectAmt: amount to attempt to Collect
    // The general rule we assert: after calling Collect, MinSum must remain equal to the value previously set with SetMinSum.
    function testFuzz_property(address addr, uint256 putAmt, uint256 collectAmt) public {
        vm.assume(addr != address(0));
        // keep some sane bounds but wide
        putAmt = bound(putAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Prepare actor with funds
        vm.deal(addr, 2 ether);

        // Set an initial MinSum value via the contract owner (this test contract)
        uint256 initialMin = 0.1 ether;
        c.SetMinSum(initialMin);

        // Ensure not initialized so SetMinSum in reference remains allowed only before Initialized
        // Now have addr Put funds (via fallback) and then call Collect
        vm.prank(addr);
        (bool okPut, ) = address(c).call{value: putAmt}("");
        // proceed regardless of okPut

        // Record MinSum before Collect
        uint256 before = c.MinSum();

        // Actor calls Collect with collectAmt
        vm.prank(addr);
        // Collect is payable in the original; call it normally
        try c.Collect(collectAmt) {
            // succeeded
        } catch {
            // ignore revert
        }

        // Exactly one assertion: MinSum must be unchanged after Collect in the correct contract
        assertTrue(c.MinSum() == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving c; inputs: caller funds and two min values
    function runTest(uint val1, uint val2) public payable {
        // ensure we have some balance if needed by calls (Put uses msg.value)
        require(address(this).balance >= 0);

        // First call to SetMinSum should succeed (when not initialized)
        c.SetMinSum(val1);

        // Do not call Initialized(); keep intitalized == false in original P
        // Second call to SetMinSum would revert in original P because code checks if(intitalized)revert();
        // In mutant M the nonReentrant_ modifier allows reentrancy that can flip intitalized during modifier execution
        // but we want a property that on original P the second call cannot succeed, i.e., the second call reverts.

        // We capture whether the second call reverts by calling it in a low-level call and observing the boolean.
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val2));

        // Assert: on the original contract, the second call must not succeed (success==false)
        // This is the distinguishing property: second SetMinSum cannot succeed when initialization flag hasn't been set externally.
        assert(!success);
    }

    // Allow contract to receive Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable attacker;
    constructor(C _c) { c = _c; attacker = payable(address(this)); }

    // We'll provide a fallback that, when reentered, calls SetMinSum to try to change MinSum.
    // In the original contract P this should be prevented by the correct nonReentrant_ modifier;
    // in the mutant M the reentrancy guard is broken and SetMinSum can execute during Collect.
    receive() external payable {
        // Attempt to reenter C and call SetMinSum. This is a state-changing call on c and must be
        // a top-level statement when invoked from run(), but calls from the fallback are allowed
        // to reenter c. We call SetMinSum with the same MinSum value to attempt a write.
        // Use a small value (0) — attacker can try to set MinSum to 0 during reentrancy.
        // Note: if SetMinSum reverts, the fallback will revert and the Collect will fail; that's acceptable.
        c.SetMinSum(0);
    }

    function run(uint deposit, uint collectAmount) public payable {
        require(address(this).balance >= deposit, "insufficient balance to fund deposit");
        // Preconditions: put some funds so Collect can withdraw and potentially trigger reentrancy.
        // Ensure deposit is >= collectAmount so Collect can succeed in withdrawing collectAmount
        require(deposit >= collectAmount, "deposit must cover requested collect amount");

        // Initialize MinSum to a nonzero value so lowering it would be observable via getter.
        // Must call SetMinSum before Initialized() is set; SetMinSum uses nonReentrant_ but that's fine now.
        c.SetMinSum(1);

        // Ensure contract is not locked by initialization and is initialized so Collect's conditions can be fulfilled.
        // We mark initialized to allow normal flows later.
        c.Initialized();

        // Put funds into the caller's account (this contract) so Collect can withdraw and trigger fallback reentry.
        c.Put{value: deposit}(0);

        // Record MinSum before the Collect call
        uint before = c.MinSum();

        // Now call Collect which will transfer funds back and, during the transfer, our fallback will reenter
        // and attempt to call SetMinSum(0). This is the call where P and M differ.
        c.Collect{value: 0}(collectAmount);

        uint after = c.MinSum();

        // General assertion: MinSum must not decrease as a result of the Collect call (no reentrant lowering).
        assert(after >= before);
    }
}

