contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use params: caller provides amounts and lock time. The test will first
    // ensure the contract is initialized and MinSum set to a value, then attempt
    // a Collect that, if reentrancy is possible, could lower MinSum via SetMinSum.
    // To observe the difference we check that MinSum after Collect is >= MinSum read before.

    function run(uint putAmount, uint lockTime, uint collectAmount, uint newMin) public payable {
        require(address(this).balance >= putAmount + collectAmount);
        // Preconditions to make Collect's body eligible to send funds:
        // 1) Ensure this test's external account has some balance recorded in c by calling Put.
        // 2) Ensure the stored balance is >= c.MinSum and >= collectAmount and that unlockTime is in the past.
        // To set MinSum and Log and mark initialized, call c.SetMinSum and c.SetLogFile and c.Initialized first.

        // Set up logging target (use this contract address cast to LogFile by caller; assume zero-address not allowed in C usage)
        c.SetLogFile(address(this));
        c.SetMinSum(1); // set initial minimal sum
        c.Initialized();

        // Fund the contract under this test's msg.sender by calling Put with value
        c.Put{value: putAmount}(lockTime);

        // Read MinSum before the Collect call
        uint beforeMin = c.MinSum();

        // Now perform Collect which in the mutant can allow reentrant SetMinSum to change MinSum during Collect
        c.Collect(collectAmount);

        uint afterMin = c.MinSum();

        // General rule: after the Collect call, MinSum must be >= beforeMin (Collect must not allow lowering MinSum via reentrancy)
        assert(afterMin >= beforeMin);
    }

    // Implement LogFile-compatible AddMessage so that SetLogFile / Put can call into this contract.
    // We do not perform any reentrant behavior here; in the mutant, reentrancy would be possible from within Collect
    // via calls to external log, but original prevents reentrancy so MinSum stays intact.
    function AddMessage(address, uint, string memory) public {
        // no-op
    }

    receive() external payable { }
}

