pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters:
    // - attackerInitial: starting ETH the attacker has to fund deposits and reentrant gas
    // - putValue: value to put into the contract (must be > 0)
    // - withdrawAmt: amount to Collect
    function testFuzz_property(uint256 attackerInitial, uint256 putValue, uint256 withdrawAmt) public {
        // keep values in wide but sensible ranges
        attackerInitial = bound(attackerInitial, 1 wei, 10 ether);
        putValue = bound(putValue, 1 wei, 5 ether);
        withdrawAmt = bound(withdrawAmt, 0 wei, 5 ether);

        Attacker attacker = new Attacker(address(c));

        // fund attacker externally
        vm.deal(address(attacker), attackerInitial);

        // initialize contract: set MinSum to a non-zero sentinel while initialized==false
        // use this test's deployer to call SetMinSum
        uint256 initialMin = 1 ether;
        c.SetMinSum(initialMin);
        // set LogFile to any address (attacker) and finalize initialization
        c.SetLogFile(address(attacker));
        c.Initialized();

        // attacker deposits some funds by calling Put via its fallback (or directly)
        // ensure attacker has enough to deposit
        uint256 deposit = bound(putValue, 1 wei, address(attacker).balance);
        attacker.deposit{value: deposit}();

        // Ensure the deposit is at least MinSum so Collect may attempt to send
        // If deposit < initialMin, try to increase deposit by calling Put again
        if (deposit < initialMin) {
            uint256 extra = initialMin - deposit;
            // top up attacker balance for extra if possible
            if (address(attacker).balance >= extra) {
                attacker.deposit{value: extra}();
                deposit += extra;
            }
        }

        // record MinSum before Collect
        uint256 minBefore = c.MinSum();

        // Now attempt Collect via attacker which will reenter and call SetMinSum if mutant allows
        // We fuzz withdrawAmt but ensure attacker attempts a non-zero withdraw when possible
        uint256 toWithdraw = bound(withdrawAmt, 0 wei, deposit);

        attacker.triggerCollect(toWithdraw);

        // After Collect completes, the invariant: MinSum must be unchanged in the correct contract
        // The mutant that allows reentrant SetMinSum can change MinSum during Collect.
        assertTrue(c.MinSum() == minBefore);
    }
}

// Minimal attacker contract that re-enters Collect by using receive and in reentry tries to call SetMinSum
contract Attacker {
    address payable public target;
    bool public reentered;

    constructor(address _t) payable {
        target = payable(_t);
    }

    // deposit into C by calling Put through fallback (C's fallback calls Put(0))
    function deposit() external payable {
        // call fallback of C which will call Put(0)
        (bool s,) = target.call{value: msg.value}("");
        require(s);
    }

    // trigger Collect on C from this contract so that receive()/fallback can reenter
    function triggerCollect(uint256 amt) external {
        // call Collect from this contract
        C(target).Collect(amt);
    }

    receive() external payable {
        // On receiving ether during Collect, attempt to call SetMinSum to change it.
        // This will succeed only if reentrancy protection is broken in the mutant.
        if (!reentered) {
            reentered = true;
            // attempt to lower MinSum to zero
            C(target).SetMinSum(0);
        }
    }
}

