    function testFuzz_property(uint256 putAmount, uint256 lockTime, uint256 collectAmount) public {
        // keep amounts in reasonable bounds and non-zero where needed
        putAmount = bound(putAmount, 1, 1 ether);
        collectAmount = bound(collectAmount, 1, 1 ether);
        // lockTime up to 1 week
        lockTime = bound(lockTime, 0, 7 days);

        // Deploy adversarial reentrant attacker that will try to call SetMinSum during Collect
        Attacker attacker = new Attacker(address(c));

        // initialize contract: set MinSum to some initial value (via non-reentrant SetMinSum)
        // ensure contract is not yet initialized so SetMinSum can be called
        vm.prank(address(this));
        c.SetMinSum(123); // set initial min sum

        // give attacker some ETH and make a deposit so Collect can be called by attacker
        vm.deal(address(attacker), putAmount);
        attacker.fundAndPut{value: putAmount}(payable(address(c)), lockTime);

        // record MinSum before Collect
        uint before = c.MinSum();

        // During Collect, the attacker will attempt a reentrant call to SetMinSum to change MinSum to 999
        // Call Collect from attacker (attacker will trigger reentrancy in its receive)
        bool ok;
        try attacker.collectOnC(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect finishes, MinSum must remain unchanged for the correct contract
        // Single assertion required: read c.MinSum()
        assertTrue(c.MinSum() == before);
    }
}

// Minimal attacker that reenters C during Collect by using receive() to call SetMinSum
contract Attacker {
    address payable public target;
    uint public reentryTargetVal = 999;

    constructor(address _target) payable {
        target = payable(_target);
    }

    // fund this contract and call Put on target
    function fundAndPut(address payable _c, uint lockTime) external payable {
        // this function is invoked with value by the test via vm.prank + direct call
        // forward the call to C.Put
        C(_c).Put{value: msg.value}(lockTime);
    }

    // call Collect on C as attacker
    function collectOnC(uint amount) external {
        // call Collect; this will trigger receive() when target sends ETH back
        C(target).Collect(amount);
    }

    // when ETH is sent during Collect, reenter SetMinSum to attempt to change MinSum
    receive() external payable {
        // try to change MinSum during the reentrant window
        // ignore failures
        try C(target).SetMinSum(reentryTargetVal) {
            // noop
        } catch {
            // noop
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - uint256 initialMin: initial MinSum to set (will be set via SetMinSum before enabling initialized())
    // - uint256 deposit: amount the attacker will deposit so Collect can try to pay out
    // - uint256 collectAmt: amount passed to Collect
    function testFuzz_property(uint256 initialMin, uint256 deposit, uint256 collectAmt) public {
        // Keep values in wide but sensible ranges to avoid trivial overflows/wastes
        initialMin = bound(initialMin, 1, type(uint256).max / 4);
        deposit = bound(deposit, 1, 1 ether);
        collectAmt = bound(collectAmt, 1, 1 ether);

        // deploy an attacker contract that will try to reenter and call SetMinSum during Collect
        Attacker attacker = new Attacker(address(c));

        // Fund attacker so it can call Put (via fallback) and later Collect
        vm.deal(address(attacker), deposit + 1 wei);

        // Set MinSum to initialMin using the non-reentrant setter before Initialized() is flipped
        // Use a regular EOA caller
        address setter = address(0xDeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF);
        vm.deal(setter, 1 ether);
        vm.prank(setter);
        c.SetMinSum(initialMin);

        // Initialize the contract to allow SetMinSum/SetLogFile/Initialized to be locked; here we set intitalized=true
        vm.prank(setter);
        c.Initialized();

        // Attacker will deposit so its balance >= MinSum and >= collectAmt and set an unlockTime in the past
        // We trigger Put by sending Ether to the contract through attacker's fallback which calls Put(0)
        // Put is also invoked by fallback(), so attacker sends directly to c via its own contract which will call c.Put(0)
        // Use attacker to call Put via fallback
        attacker.fundAndPut{value: deposit}(deposit);

        // sanity: attacker.balance in C should now be >= deposit
        // Now attempt Collect from attacker contract which will receive the low-level call and during receive will reenter to call SetMinSum
        // We fuzz the newMin value attacker will try to set during reentrancy via collectAmt parity: derive newMin from collectAmt to keep fuzzer in control
        uint256 newMin = collectAmt; // fuzzed-influenced choice
        attacker.setReentrantTarget(newMin);

        // Record MinSum before Collect
        uint256 before = c.MinSum();

        // Now perform Collect via attacker; attacker will call c.Collect(collectAmt)
        bool ok;
        try attacker.tryCollect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call completes, on the correct contract MinSum must remain unchanged for ALL admissible inputs
        // The mutant that fails to restore the lock allows the reentrant SetMinSum from the attacker to change MinSum
        uint256 after = c.MinSum();

        // Single assertion observing the contract's public state
        assertTrue(before == after);
    }
}

// Minimal attacker contract that, when receiving funds during Collect's low-level call to msg.sender.call{value: _am}("")
// will reenter C and call SetMinSum with the chosen value.
contract Attacker {
    C target;
    uint256 public reentrantNewMin;

    constructor(address _t) {
        target = C(_t);
    }

    // Called by test to set what the attacker will try to set during reentrancy
    function setReentrantTarget(uint256 _newMin) external {
        reentrantNewMin = _newMin;
    }

    // Fund attacker and provoke Put by sending ether to C via fallback (which calls Put(0))
    function fundAndPut(uint256 _val) external payable {
        // caller should send msg.value to this contract; then forward to c via fallback invocation
        // We directly call C.Put to ensure the Holder is set up
        target.Put{value: msg.value}(0);
    }

    // Try to call Collect on C; will be the recipient of the low-level call
    function tryCollect(uint256 _amt) external {
        target.Collect(_amt);
    }

    // When C executes (bool _s, bytes memory _d) = msg.sender.call{value: _am}("");
    // this fallback/receive will be executed. We use that opportunity to reenter and call SetMinSum.
    receive() external payable {
        // Reenter and attempt to change MinSum
        // We call SetMinSum(reentrantNewMin)
        // Surround with try/catch to avoid bubbling reverts to the original call if SetMinSum reverts
        try target.SetMinSum(reentrantNewMin) {
            // ignore
        } catch {
            // ignore failures
        }
    }
}

