contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: attackerInitialBalance (eth to seed attacker), putAmount (amount deposited by attacker), setMinNew (value attacker will attempt to set via reentrancy)
    function testFuzz_property(uint256 attackerInitialBalance, uint256 putAmount, uint256 setMinNew) public {
        // keep values in wide admissible ranges
        attackerInitialBalance = bound(attackerInitialBalance, 1 wei, 10 ether);
        putAmount = bound(putAmount, 1 wei, attackerInitialBalance);
        // setMinNew can be any uint256; keep wide

        // Deploy adversarial contract that will reenter Collect's external call to msg.sender.call and attempt to call SetMinSum during reentry
        Attacker attacker = new Attacker(c);

