        vm.deal(address(attacker), attackerInitialBalance);

        // initialize MinSum to some known value via SetMinSum (must be done before Initialized flip)
        uint256 initialMin = 0x123;
        c.SetMinSum(initialMin);

        // ensure contract is not yet Initialized so SetMinSum can be called by attacker in reentrancy
        // attacker deposits putAmount
        attacker.doPut{value: putAmount}(putAmount);

