import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor address to be used as the new log file, and a boolean deciding whether to initialize first
    function testFuzz_property(address newLog, bool doInit) public {
        // keep newLog non-zero to be a realistic contract address (fuzzer may choose zero)
        vm.assume(newLog != address(0));

        // Deploy a minimal LogFile contract at that address if it is a contract-like address.
        // We cannot deploy to an arbitrary address, so instead always deploy a real LogFile and use its address.
        // The fuzzer still provides `newLog` which influences coverage; we will use the deployed one's address
        // when calling SetLogFile to ensure the call succeeds and behaves like a normal contract.
        LogFile lf = new LogFile();
        address chosen = address(lf);

        // Step 1: optionally initialize the contract (this should flip intitalized true)
        if (doInit) {
            c.Initialized();
        }

        // Record the Log address before calling SetLogFile
        address before = address(getLogAddress(c));

        // Call SetLogFile with the chosen deployed LogFile address
        // We must capture whether the call succeeded (the reference reverts on intialized==true path via revert())
        bool ok;
        try c.SetLogFile(chosen) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, read the stored Log address
        address after = address(getLogAddress(c));

        // General invariant: If the contract was initialized before the SetLogFile call, then the reference
        // implementation will not change the stored Log address (call either reverts or leaves it unchanged).
        // Therefore, when doInit == true, after must equal before for the correct contract.
        // The mutant removes the guard and will allow changing Log, so for some inputs this assertion will fail.
        if (doInit) {
            assertTrue(after == before);
        } else {
            // If not initialized, SetLogFile should succeed and set Log to chosen. We assert that after equals chosen.
            // This also keeps the property valid across all inputs for the reference implementation.
            assertTrue(after == chosen);
        }
    }

    // Helper to read the public Log variable via the autogenerated getter signature.
    // Because Log is of type LogFile (a contract type), the getter has signature function Log() public view returns (LogFile);
    // We call it via an interface-like call
    function getLogAddress(C _c) internal returns (address) {
        // Use low-level staticcall to invoke the auto getter 'Log()' (selector = bytes4(keccak256("Log()"))).
        (bool s, bytes memory ret) = address(_c).call(abi.encodeWithSelector(bytes4(keccak256("Log()"))));
        if (!s || ret.length < 32) return address(0);
        address addr;
        assembly { addr := mload(add(ret,32)) }
        return addr;
    }
}

contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

